@implementation MuInventoryView{std::shared_ptr<const mu::client::InventorySnapshot> snapshot;std::shared_ptr<const mu::ui::ItemCatalog> catalog;mu::ui::Texts texts;NSMutableDictionary<NSNumber*,NSImage*>* icons;}
