- (void)refreshDrag{if(snapshot)[self.dragController registerContainer:0 view:self items:snapshot->items root:self.assetRoot.UTF8String language:self.language.UTF8String];}
- (void)viewDidMoveToSuperview{[super viewDidMoveToSuperview];self.wantsLayer=YES;}
- (BOOL)isFlipped{return YES;}
- (void)setFrameSize:(NSSize)size{[super setFrameSize:size];if(snapshot)[self updateItems:snapshot];}
- (void)resizeWithOldSuperviewSize:(NSSize)size{auto game=self.superview;if(!game)return;CGFloat scale=std::min(game.bounds.size.width/640.,game.bounds.size.height/480.);self.frame=NSMakeRect(game.bounds.size.width-190*scale,game.bounds.size.height-429*scale,190*scale,429*scale);}
