- (void)updateTrackingAreas{[super updateTrackingAreas];for(NSTrackingArea* area in self.trackingAreas)[self removeTrackingArea:area];[self addTrackingArea:[[NSTrackingArea alloc] initWithRect:NSZeroRect options:NSTrackingMouseMoved|NSTrackingMouseEnteredAndExited|NSTrackingActiveInKeyWindow|NSTrackingInVisibleRect owner:self userInfo:nil]];}
- (void)mouseExited:(NSEvent*)event{[self.tooltip hide];[self.hoverView hide];[self.effectsLayer hideSlot:nil];self.hoverSlot=nil;[self refreshPicked];self.needsDisplay=YES;}
- (void)mouseMoved:(NSEvent*)event{auto point=[self convertPoint:event.locationInWindow fromView:nil];point.x*=190/self.bounds.size.width;point.y*=429/self.bounds.size.height;int selected=-1;for(auto& part:equipment)if(NSPointInRect(point,part.rect))selected=part.slot;if(snapshot)for(auto& pair:snapshot->items)if(pair.first>=12&&pair.first<76){auto& item=catalog->at(pair.second.index);if(NSPointInRect(point,NSMakeRect(15+(pair.first-12)%8*20,200+(pair.first-12)/8*20,item.width*20,item.height*20)))selected=pair.first;}if(!snapshot||selected<0||!snapshot->items.count(selected)){[self.tooltip hide];[self.hoverView hide];[self.effectsLayer hideSlot:nil];self.hoverSlot=nil;self.needsDisplay=YES;return;}auto& selectedItem=snapshot->items.at(selected);auto& metadata=catalog->at(selectedItem.index);NSRect itemRect=NSZeroRect;for(auto& part:equipment)if(part.slot==unsigned(selected))itemRect=part.rect;if(selected>=12)itemRect=NSMakeRect(15+(selected-12)%8*20,200+(selected-12)/8*20,metadata.width*20,metadata.height*20);CGFloat factor=self.bounds.size.width/190;itemRect=NSMakeRect(itemRect.origin.x*factor,itemRect.origin.y*factor,itemRect.size.width*factor,itemRect.size.height*factor);if(!self.hoverView)self.hoverView=[MuHoveredItemView new];[self.hoverView showItem:selectedItem root:self.assetRoot.UTF8String language:self.language.UTF8String rect:itemRect inView:self];if(![self.hoverSlot isEqualToNumber:@(selected)])self.needsDisplay=YES;self.hoverSlot=@(selected);[self.effectsLayer hideSlot:self.hoverSlot];if(!self.tooltip)self.tooltip=[MuItemTooltip new];auto cursor=[self.superview convertPoint:event.locationInWindow fromView:nil];auto requirements=self.dragController?[self.dragController attributes]:mu::client::EquipmentAttributes{};[self.tooltip showStyledText:mu::ui::item_tooltip_styled(snapshot->items.at(selected),*catalog,texts,self.bounds.size.width/190,requirements.ready?&requirements:nullptr) atPoint:cursor inView:self.superview scale:self.bounds.size.width/190];}
- (NSString*)view:(NSView*)view stringForToolTip:(NSToolTipTag)tag point:(NSPoint)point userData:(void*)data{unsigned slot=std::uintptr_t(data)-1;if(!snapshot)return nil;auto item=snapshot->items.find(slot);return item==snapshot->items.end()?nil:mu::ui::item_tooltip(item->second,*catalog,texts);}
- (void)image:(NSString*)key rect:(NSRect)rect{[self.images[key] drawInRect:rect fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1 respectFlipped:YES hints:nil];}
- (void)itemAt:(unsigned)slot rect:(NSRect)rect{if(!snapshot||[self.dragController hidesItemInContainer:0 slot:slot])return;auto item=snapshot->items.find(slot);if(item!=snapshot->items.end()){auto color=mu::ui::item_background_color(item->second,catalog->at(item->second.index));if(slot>=12||color.alphaComponent<.5){[color setFill];if(slot>=12){for(unsigned y=0;y<catalog->at(item->second.index).height;y++)for(unsigned x=0;x<catalog->at(item->second.index).width;x++)NSRectFillUsingOperation(NSMakeRect(rect.origin.x+x*20+1,rect.origin.y+y*20+1,18,18),NSCompositingOperationSourceOver);}else NSRectFillUsingOperation(NSInsetRect(rect,2,2),NSCompositingOperationSourceOver);}}if(self.hoverView.superview&&[self.hoverSlot isEqualToNumber:@(slot)])return;if([self.effectsLayer rendersSlot:slot])return;auto found=snapshot->items.find(slot);if(found==snapshot->items.end())return;auto& displayedItem=found->second;if(NSImage* image=icons[@(slot)]){[image drawInRect:rect fromRect:NSZeroRect operation:NSCompositingOperationSourceOver fraction:1 respectFlipped:YES hints:nil];return;}[mu::ui::item_name(displayedItem,*catalog) drawInRect:NSInsetRect(rect,2,2) withAttributes:@{NSFontAttributeName:mu::ui::source_font(7),NSForegroundColorAttributeName:NSColor.systemYellowColor}];}
- (void)drawRect:(NSRect)dirty{
 [NSGraphicsContext saveGraphicsState];auto transform=[NSAffineTransform transform];[transform scaleXBy:self.bounds.size.width/190 yBy:self.bounds.size.height/429];[transform concat];
