 for(auto& part:equipment){[self image:[NSString stringWithUTF8String:part.image] rect:part.rect];[self itemAt:part.slot rect:part.rect];}
 for(unsigned row=0;row<8;row++)for(unsigned column=0;column<8;column++){auto cell=NSMakeRect(15+column*20,200+row*20,20,20);[self image:@"cell" rect:cell];}
