 [self image:@"money" rect:NSMakeRect(11,364,170,26)];[self.money drawInRect:NSMakeRect(50,371,124,16) withAttributes:@{NSFontAttributeName:mu::ui::source_font(10),NSForegroundColorAttributeName:self.moneyColor}];const char* buttons[]={"exit","repair","shop"};for(unsigned i=0;i<3;i++){auto image=self.images[[NSString stringWithUTF8String:buttons[i]]];[image drawInRect:NSMakeRect(13+i*37,391,36,29) fromRect:NSMakeRect(0,image.size.height-29,36,29) operation:NSCompositingOperationSourceOver fraction:i?.45:1 respectFlipped:YES hints:nil];}
