}
- (void)mouseDragged:(NSEvent*)event{[self.tooltip hide];[self.hoverView hide];[self.effectsLayer hideSlot:nil];self.hoverSlot=nil;self.needsDisplay=YES;[self.dragController drag:event];}
- (void)mouseDown:(NSEvent*)event{if(self.repairMode)return;[self.dragController begin:event inView:self];[self.tooltip hide];[self.hoverView hide];[self.effectsLayer hideSlot:nil];self.hoverSlot=nil;self.needsDisplay=YES;}
- (void)mouseUp:(NSEvent*)event{if(self.repairMode&&!self.dragController.pending){auto p=[self convertPoint:event.locationInWindow fromView:nil];p.x*=190/self.bounds.size.width;p.y*=429/self.bounds.size.height;int cell=mu::ui::equipment_cell(p.x,p.y);if(cell<0&&p.x>=15&&p.x<175&&p.y>=200&&p.y<360)cell=12+int((p.y-200)/20)*8+int((p.x-15)/20);if(snapshot&&cell>=0){int slot=mu::ui::item_at_cell(snapshot->items,*catalog,0,cell);if(slot>=0&&self.repairHandler){self.repairHandler(slot);return;}}}if([self.dragController finish:event])return;auto p=[self convertPoint:event.locationInWindow fromView:nil];p.x*=190/self.bounds.size.width;p.y*=429/self.bounds.size.height;if((NSPointInRect(p,NSMakeRect(169,7,13,12))||NSPointInRect(p,NSMakeRect(13,391,36,29)))&&self.closeHandler){self.closeHandler();return;}[self mouseMoved:event];}
